// tasogare.js
// Event functions of 黄昏のエチュード. Load this after avg.js in each scene's HTML.
// (generated by scenario/tasogare/game/write.js)

const PERSON_IMG_CLASS = 'img-person1';

// overlay a person's image on the scene image (img/person-<name>.png)
const showPersonImage = function (name) {
	$('#image-area .' + PERSON_IMG_CLASS).remove();
	$('#image-area').append($('<img>', { src: '../img/person-' + name + '.png', addClass: PERSON_IMG_CLASS }));
};
const hidePersonImage = function () {
	$('#image-area .' + PERSON_IMG_CLASS).remove();
};

// show the person and switch to person mode
const showPerson = function (name) {
	showPersonImage(name);
	setPersonMode(name);
	getCommands(getSceneId());
	return true;
};
["yukari","kazue","kaede","katsuragi","ritsuko","tsurumi","hori","mori","shibata","fumi","sugawara","otowa","guard","neighbor"].forEach(function (name) {
	const cap = name.split('-').map(function (w) { return w[0].toUpperCase() + w.slice(1); }).join('');
	sceneEvents['show' + cap] = function () { return showPerson(name); };
	sceneEvents['img' + cap] = function () { showPersonImage(name); return true; };
});
// pictures that only replace the image (a partner walking along, an expression)
["katsuragi-broken","kaede-tears","yukari-serious"].forEach(function (name) {
	const cap = name.split('-').map(function (w) { return w[0].toUpperCase() + w.slice(1); }).join('');
	sceneEvents['img' + cap] = function () { showPersonImage(name); return true; };
});

// a command whose choices answer a question: show the question (message Q00) instead of the common 「……」
const QUESTION_COMMANDS = ['AC1', 'THK'];
document.addEventListener('click', function (e) {
	const li = e.target.closest && e.target.closest('#command-list li');
	if (!li || QUESTION_COMMANDS.indexOf(li.id) < 0) return;
	e.stopImmediatePropagation();
	e.preventDefault();
	if (!isOk) return;
	isOk = false;
	const sceneId = getSceneId();
	const flag = getFlag();
	execAjax('../api/message', { sceneId: sceneId, commandId: li.id, targetId: 'Q00', flag: flag }, function (q) {
		execAjax('../api/target', { sceneId: sceneId, commandId: li.id, flag: flag }, function (data) {
			// no question for this flag (the engine answers 'ERROR: No message!'): the command's usual message
			const ask = q && q.message && q.message.indexOf('^') < 0 && q.message.indexOf('ERROR:') !== 0 ? q.message : data.message;
			// while 考える asks a question, its usual 「これからのこと」 (the hint, THK 001) is not one of the answers
			const asking = ask !== data.message;
			const commands = (data.commands || []).filter(function (t) { return !(asking && li.id === 'THK' && t.targetId === '001'); });
			if (commands.length > 0) showCommands({ message: ask, commands: commands });
			else showMessage(data);
		});
	});
}, true);

// one-click commands: the top-level 「話す」 and 「話を切り上げる」 run their target at once
const DIRECT_COMMANDS = ['TKX', 'END', 'EAT'];
const runDirect = function (commandId) {
	if (!isOk) return;
	isOk = false;
	const sceneId = getSceneId();
	const flag = getFlag();
	execAjax('../api/target', { sceneId: sceneId, commandId: commandId, flag: flag }, function (data) {
		const t = data.commands && data.commands[0];
		if (t) {
			getMessage(sceneId, commandId, t.targetId, flag);
			getCommands(sceneId);
		} else {
			showMessage(data);
		}
	});
};
document.addEventListener('click', function (e) {
	const li = e.target.closest && e.target.closest('#command-list li');
	if (!li || DIRECT_COMMANDS.indexOf(li.id) < 0) return;
	e.stopImmediatePropagation();
	e.preventDefault();
	runDirect(li.id);
}, true);
// one-click commands are hidden when they have nothing to do; 「話す」 also shows whom: 「ゆかりさんと話す」
const NAMED_BY_TARGET = ['TKX'];
$(function () {
	const list = document.getElementById('command-list');
	if (!list) return;
	new MutationObserver(function () {
		['TKX', 'EAT'].forEach(function (id) {
			const li = document.getElementById(id);
			if (!li || li.dataset.checked) return;
			li.dataset.checked = '1';
			execAjax('../api/target', { sceneId: getSceneId(), commandId: id, flag: getFlag() }, function (data) {
				const t = data.commands && data.commands[0];
				if (!t) $(li).remove();
				else if (NAMED_BY_TARGET.indexOf(id) >= 0) $(li).text(t.text);
			});
		});
	}).observe(list, { childList: true });
});

sceneEvents.hidePerson = function () {
	hidePersonImage();
	setPersonMode('');
	getCommands(getSceneId());
	return true;
};
sceneEvents.hideImage = function () { hidePersonImage(); return true; };
sceneEvents.clearGame = function () { $('#command-area').html(''); return true; };

