// continuation of a long text: nxNNN loads MESSAGE (scene, 'NXT', 'NNN').
// It runs after avg.js has finished the current text, then locks the commands again.
for (let i = 1; i <= 999; i++) {
	const id = String(i).padStart(3, '0');
	sceneEvents['nx' + id] = function () {
		setTimeout(function () {
			isOk = false;
			$('#command-list li').addClass('disabled');
			getMessage(getSceneId(), 'NXT', id, getFlag());
		}, 0);
		return true;
	};
}

/* --------------------------------------------------
* sound: an overlay track (the piano, the record) plays over a paused BGM
* -------------------------------------------------- */
let overlay = null;
const isMuted = function () {
	const bgm = document.getElementById('bgm-audio');
	if (bgm) return bgm.muted;
	return sessionStorage.getItem('tasogare:AVG_BGM_MUTED') === 'true';
};
const playOverlay = function (file, loop) {
	const bgm = document.getElementById('bgm-audio');
	if (bgm) bgm.pause();
	if (overlay) overlay.pause();
	overlay = new Audio('../audio/' + file + '.mp3');
	overlay.loop = loop;
	overlay.muted = isMuted();
	overlay.play().catch(function () {});
};
const playSe = function (file) {
	const se = new Audio('../audio/' + file + '.mp3');
	se.muted = isMuted();
	se.play().catch(function () {});
};
// keep the overlay in step with the BGM mute button of bgm.js
document.addEventListener('click', function (e) {
	if (e.target && e.target.id === 'bgm-toggle' && overlay) {
		setTimeout(function () { overlay.muted = isMuted(); }, 0);
	}
}, true);

sceneEvents.bgmStop = function () {
	const bgm = document.getElementById('bgm-audio');
	if (bgm) bgm.pause();
	if (overlay) { overlay.pause(); overlay = null; }
	return true;
};
sceneEvents.bgmGhost = function () { playOverlay('bgm-ghost', true); return true; };
sceneEvents.bgmRecord = function () { playOverlay('bgm-record', false); return true; };
sceneEvents.bgmEtude = function () { playOverlay('bgm-etude-full', false); return true; };
sceneEvents.bgmCrisis = function () { playOverlay('bgm-crisis', true); return true; };
sceneEvents.sePhone = function () { playSe('se-phone'); return true; };
sceneEvents.seKnock = function () { playSe('se-knock'); return true; };
sceneEvents.seCreak = function () { playSe('se-creak'); return true; };
sceneEvents.seBell = function () { playSe('se-bell'); return true; };
sceneEvents.seCrash = function () { playSe('se-crash'); return true; };
sceneEvents.seNoise = function () { playSe('se-noise'); return true; };

/* --------------------------------------------------
* screen effects
* -------------------------------------------------- */
const effect = function (cls, ms) {
	const area = document.getElementById('main-area');
	area.classList.remove(cls);
	void area.offsetWidth;
	area.classList.add(cls);
	setTimeout(function () { area.classList.remove(cls); }, ms);
};
sceneEvents.shake = function () { effect('fx-shake', 600); return true; };
sceneEvents.flash = function () {
	$('<div class="fx-flash"></div>').appendTo('#image-area');
	setTimeout(function () { $('#image-area .fx-flash').remove(); }, 1200);
	return true;
};
sceneEvents.fadeOut = function () { $('<div class="fx-black"></div>').appendTo('#image-area'); return true; };
sceneEvents.fadeIn = function () { $('#image-area .fx-black').remove(); return true; };
sceneEvents.chalk = function () {
	if (!$('#image-area .fx-chalk').length) $('<div class="fx-chalk">次はおまえ</div>').appendTo('#image-area');
	return true;
};
sceneEvents.chalkOff = function () { $('#image-area .fx-chalk').remove(); return true; };
sceneEvents.redSky = function () { $('#image-area').addClass('fx-red'); return true; };

/* --------------------------------------------------
* evidence: a chime and a small label on the picture
* -------------------------------------------------- */
const showFound = function (label) {
	playSe('se-found');
	const el = $('<div class="fx-found"></div>').text('◆ ' + label).appendTo('#image-area');
	setTimeout(function () { el.remove(); }, 2800);
};
const ITEM_NAMES = {"I01":"楽譜の写真","I02":"学校新聞のコピー","I03":"時計塔の鍵","I04":"赤い土","I05":"ゆかりの手帳","I06":"透子の練習帳","I07":"『黄昏』のレコード","I08":"咲の日記の切れ端","I09":"最後のページ"};
Object.keys(ITEM_NAMES).forEach(function (id) {
	sceneEvents['found' + id] = function () { showFound(ITEM_NAMES[id]); return true; };
});
sceneEvents.clue = function () { showFound('手がかり'); return true; };
